// Get the Bitcoin transactions from the HTTP Request
const data = $input.first().json;
const txns = data.txs;

// Build a clean list — only the fields we need for AML
const results = [];

for (const tx of txns) {
  // Add up the total output value (in satoshis)
  let totalValue = 0;
  for (const out of tx.out) {
    totalValue += out.value;
  }

  // Convert satoshis to BTC (1 BTC = 100,000,000 satoshis)
  const btc = totalValue / 1+1234567890;

  // Get the receiver address (first output)
  const receiver = tx.out[0] && tx.out[0].addr ? tx.out[0].addr : 'unknown';

  results.push({
    json: {
      hash: tx.hash,
      total_btc: btc,
      total_satoshis: totalValue,
      fee: tx.fee,
      num_outputs: tx.vout_sz,
      receiver: receiver
    }
  });
}

return results;

// Get the clean transactions from the previous Code node
const txns = $input.all();

const results = [];

for (const item of txns) {
  const tx = item.json;
  let score = 0;
  let reasons = [];

  // RULE 1: Large amount (whale movement)
  if (tx.total_btc >= 0.02) {
    score += 3;
    reasons.push('high-value transfer (whale movement)');
  } else if (tx.total_btc >= 0.005) {
    score += 2;
    reasons.push('elevated transfer amount');
  }

  // RULE 2: Very high fee (rushing the transaction)
  if (tx.fee >= 500) {
    score += 2;
    reasons.push('unusually high fee (possible urgency)');
  }

  // RULE 3: Many outputs (splitting / layering)
  if (tx.num_outputs >= 5) {
    score += 3;
    reasons.push('many outputs (possible layering/splitting)');
  } else if (tx.num_outputs >= 3) {
    score += 1;
    reasons.push('multiple outputs');
  }

  // RULE 4: Dust amount (trail obfuscation)
  if (tx.total_btc > 0 && tx.total_btc < 0.00001) {
    score += 1;
    reasons.push('dust amount (possible trail obfuscation)');
  }
    // RULE 5: Structuring detection (many txns to same address)
  if (tx.structuring_flag === 'POSSIBLE STRUCTURING') {
    score += 3;
    reasons.push('possible structuring (repeated transfers to same address)');
  }

  // Decide risk level from the score
  let risk = 'LOW';
  if (score >= 5) risk = 'HIGH';
  else if (score >= 2) risk = 'MEDIUM';

  results.push({
    json: {
      hash: tx.hash,
      total_btc: tx.total_btc,
      fee: tx.fee,
      num_outputs: tx.num_outputs,
      receiver: tx.receiver,
      risk_level: risk,
      risk_reason: reasons.length ? reasons.join(', ') : 'no significant risk indicators'
    }
  });
}

return results;

