// Get all clean transactions
const txns = $input.all();

// Count how many transactions go to each receiver
const addressCount = {};
for (const item of txns) {
  const addr = item.json.receiver;
  addressCount[addr] = (addressCount[addr] || 0) + 1;
}

// Add a "structuring flag" to each transaction
const results = [];
for (const item of txns) {
  const tx = item.json;
  const count = addressCount[tx.receiver];

  // Flag if this address received 3+ transactions
  const structuring = count >= 3;

  results.push({
    json: {
      ...tx,
      address_txn_count: count,
      structuring_flag: structuring ? 'POSSIBLE STRUCTURING' : 'normal'
    }
  });
}

return results;
